_upd('def:hasse-general', text=r'The Hasse invariant $\gamma$ of an arbitrary elliptic $E\,|\,K$: the class in $K^\times/K^{\times2}$ (resp.\ $K^+/\pi K^+$) whose image over a splitting field $L$ is the Hasse invariant of $EL\,|\,L$.', uses=['def:splitting-data', 'def:hasse-invariant'])
